"""Evidence-led full-cycle extension; preserve prior results and native math."""
import json,re
from copy import deepcopy
from pathlib import Path
from docx import Document
from docx.shared import Cm,Pt
from build_v17 import write
from build_corrected_manuscript import paragraph,table
ROOT=Path(__file__).resolve().parents[1];OLD=ROOT/'revision_18_2026-11-01';OUT=ROOT/'revision_19_2026-11-01'
def f(x):return '—' if x is None else f'{x:.3g}'
def cells(t):return [[c.text for c in r.cells] for r in t.rows]

def main():
    a=json.loads((OUT/'analysis_v19.json').read_text());audit=json.loads((OUT/'audit_cycle_v19.json').read_text());assert audit['states']==726
    coarse,fine=a['cycle'];inv=a['inverse'];assert len(a['approximation'])==2
    best=[];rows=[]
    for source,label in [('inverse_analytic.json','Analytical'),('inverse_reference_s0.08.json','Moving 0.08'),('inverse_reference_s0.04.json','Moving 0.04')]:
        for design,short in [('interior','Interior'),('with_transitions','Mixed')]:
            rr=[r for r in inv if r['file']==source and r['design']==design and 'cost' in r]
            b=min([r for r in rr if not r['restricted']],key=lambda r:r['cost']);n=min([r for r in rr if r['restricted']],key=lambda r:r['cost']);best.append(b)
            th=b['theta'];rows.append([label+' / '+short,f(th[0]*1000)+' / '+f(th[1]),f(th[2]*1000)+' / '+f(th[3]),f(b['residual_RMS_um']),f(n['residual_RMS_um']),f(b.get('full_cycle_prediction_RMS_um')),'C' if b['success'] else 'L'])
    failures=sum(not r.get('success',False) for r in inv);attempts=len(inv)
    d=Document(OLD/'MMT_manuscript_Q1_revision_v18_clean.docx');changes=[]
    def patch(prefix,text):
        p=next(p for p in d.paragraphs if p.text.startswith(prefix));changes.append(dict(before=p.text,after=text));write(p,text);return p
    abstract=('Inferring gear microgeometry from transmission error requires distinguishing exact invisibility from weak sensitivity and operator discrepancy. We prove that nonnegative relief outside loaded support is exactly invisible under fixed geometry and compliance, including coupled tooth pairs. Synthetic likelihood and Monte Carlo studies show that nonzero local sensitivity does not guarantee reliable depth and start recovery. A 5% gain perturbation raises deeper-case median scaled error from 0.0916 to 1.86 across 200 paired realizations. Fixed-normal finite-element controls detect a dedendum signal while allowing compensating inverse profiles. A separate bilateral moving-contact model resolves 120 stations for three profiles at two resolutions, including 18 stations omitted by the earlier generator. Its fine-grid isolated, mean-removed dedendum signal is '+f(fine['dedendum_centered_RMS_um'])+' µm RMS; the corresponding refinement difference is '+f(a['dedendum_contrast_refinement_RMS_um'])+' µm. Equal-count inverse designs assess the added stations under nominal-elasticity approximation. Discrete contact verification and selected independent-solver checks support operator-conditioned conclusions, without establishing continuum-converged reconstruction or physical profile recovery. The resulting protocol checks loaded support, numerical discrepancy and restricted alternatives before inversion.')
    abstract=abstract.replace('Discrete contact verification','Inverse estimates shift with reference resolution despite small transmission residuals. Discrete contact verification')
    assert len(abstract.split())<=180;patch('Inferring gear microgeometry',abstract)
    p=next(p for p in d.paragraphs if p.text.startswith('Research question and contributions.'))
    patch('Research question and contributions.',p.text.replace('mesh, interface and material-removal controls and an external amplitude benchmark','mesh, interface and material-removal controls, a separate bilateral full-cycle generator, equal-count transition designs, selected independent-solver checks and an external amplitude benchmark'))
    p=next(p for p in d.paragraphs if p.text.startswith('The evidence is organized'))
    patch('The evidence is organized',p.text.replace('Table 10 in Section 5','Section 4.8 tests noise and operator stress; Section 4.9 adds the separate updated-contact cycle and equal-count inverse designs. Table 10 in Section 5'))
    # Renumber the existing evidence table, retaining its contents.
    for p in d.paragraphs:
        if 'Table 10' in p.text:write(p,p.text.replace('Table 10','Table 11'))
    evidence=next(t for t in d.tables if t.cell(0,0).text=='Evidence')
    extra=[['Noise and operator stress','4.8','Gain, correlation, periodic errors and covariance estimation change bounded inverse errors and transfer under specified synthetic alternatives','Measured error calibration; physical parameter coverage'],['Full-cycle bilateral contact','4.9','All 120 stations for three virtual profiles at two resolutions; equal-count inversions and selected independent-solver controls','Certified manufactured geometry; continuum-converged inversion; unique physical relief recovery']]
    for values in extra:
        newrow=deepcopy(evidence.rows[-1]._tr)
        for node in newrow.iter():
            for key in list(node.attrib):
                if key.endswith('}paraId') or key.endswith('}textId'):del node.attrib[key]
        evidence._tbl.append(newrow)
        for cell,value in zip(evidence.rows[-1].cells,values):
            p=cell.paragraphs[0];write(p,value)
            for r in p.runs:r.font.size=Pt(9)
    anchor=next(p for p in d.paragraphs if p.text=='5 Discussion')
    def add(text,style=None):
        p=paragraph(d,'',style);write(p,text);anchor._p.addprevious(p._p);return p
    def cap(text):
        p=add(text);p.paragraph_format.keep_with_next=True;p.paragraph_format.keep_together=True
        for r in p.runs:r.font.size=Pt(9)
        return p
    add('4.9 Full-cycle updated contact and equal-count inverse designs','Heading 2')
    add('A separate virtual experiment addresses the transition stations omitted in Section 4.5. The frictionless generator updates projections and normals on both deformed contours and imposes nonpenetration in both node-to-segment directions. It uses the 24/24 pair, 300 Nm, m=3 mm, width 20 mm, centre distance 72 mm, E=210000 MPa and ν=0.30; an assumed 12 mm bore is clamped relative to rigid hub motion. Linear triangular elements describe small-strain plane-strain body elasticity, combined with finite rigid rotation and iterated contact geometry. No beam, Hertz or half-space compliance is added to the FE elasticity. Non-Hertzian contact and tip-corner LTCA studies motivate separating geometry and compliance assumptions [46,47]; their results are not adopted as validation data. The quadratic root blend, 0.4 mm root trim and sharp tips are assumed contours, not certified manufactured geometry.')
    add('The three pinion profiles are nominal, addendum-only and combined relief, with combined truth θ=(0.020,0.75,0.010,0.50), depths in mm and exponent p=2. The modified upper involute is extended to the original tip circle. Each prescribed profile is separately meshed and its elastic stiffness reassembled. The same body-coordinate mesh is retained over the entire cycle; contact search includes the full near-mesh contours of five teeth and does not constrain contact to the theoretical line of action. Two surface/bulk spacings, 0.04/0.50 mm and 0.02/0.35 mm, give 120 stations f=i/120, i=0,…,119, per profile, plus f=1 as a closure control: 720 cycle observations and six closure controls. The former omissions are i=24–32 and 88–96. This new operator supplies a separate data set; it does not replace the archived 102-station fixed-normal observations.')
    add('At each iteration a nonnegative convex contact problem satisfies the actual 300 Nm torque using current lever arms, rather than a fixed base-circle force. Tiny dual regularization is 10⁻⁸ times the median contact-compliance diagonal. Spatial segment screening and constraint generation accelerate exactly the same candidate problem; omitted constraints are checked by full-candidate KKT residuals. Equivalence receipts, full-problem fallbacks and source histories are archived. Every accepted state is checked again from saved displacements and contact forces for both projection directions, global polygon overlap, equilibrium, positive elastic energy and FE consistency. Across 726 states, maximum recomputed active gap is '+f(max(r['active_gap_um'] for r in audit['results']))+' µm and maximum torque relative error is '+f(max(r['torque_relative_error'] for r in audit['results']))+'. These residuals verify the discrete implementation, not continuum accuracy (Table S33).')
    add('The full-cycle responses in Figure 13 separate the isolated dedendum contrast from total TE. The mean-removed combined-minus-addendum signal is '+f(coarse['dedendum_centered_RMS_um'])+' and '+f(fine['dedendum_centered_RMS_um'])+' µm RMS on the coarse and fine grids; their pointwise contrast difference is '+f(a['dedendum_contrast_refinement_RMS_um'])+' µm RMS. Mean-removed combined TE changes by '+f(a['cycle_centered_refinement_RMS_um']['combined'])+' µm RMS. The fine-grid dedendum contrast has '+f(fine['dedendum_excluded_RMS_um'])+' µm RMS on the 18 former omissions and '+f(fine['dedendum_interior_RMS_um'])+' µm RMS on the other 102 stations, using the same full-cycle offset removal. The f=1 minus f=0 closure errors for nominal, addendum and combined profiles are '+', '.join(f(fine['cases'][k]['closure_um']) for k in ['nominal','addendum','combined'])+' µm. They are retained without detrending or periodic enforcement. Two grids do not certify an asymptotic error bound or nanometre-scale structural sensitivity.')
    add('On the 18 former omissions specifically, combined-profile refinement changes the centred observable by '+f(a['transition_centered_refinement_RMS_um']['combined'])+' µm RMS, below the historical 0.18 µm differential-signal scale. This meets an empirical last-two-grid criterion for the declared mean-removed observable. The corresponding uncentred approach change is '+f(a['transition_raw_refinement_RMS_um']['combined'])+' µm RMS; the result does not certify absolute approach accuracy, a continuum error bound or resolution of the separate nanometre-scale structural effect.')
    pic=d.add_paragraph();pic.paragraph_format.keep_with_next=True;pic.add_run().add_picture(str(OUT/'cycle_v19.png'),width=Cm(16.2));anchor._p.addprevious(pic._p)
    cap('Figure 13 Full-cycle updated-contact controls. Surface/bulk spacings identify each curve. Shaded regions contain the 18 stations excluded by the historical fixed-normal generator. Panels distinguish modified-profile TE, the isolated dedendum contrast, refinement discrepancy and the nominal-elasticity inverse approximation evaluated at the known truth. Each curve is mean-removed over all 120 stations; no smoothing or forced periodic closure is applied.').paragraph_format.keep_with_next=False
    add('A separate inverse model updates the bilateral contact geometry on a fixed material-coordinate grid while retaining nominal FE compliance. It therefore approximates, rather than duplicates, the generating elasticity. At the truth, its full-cycle centred discrepancies against the fine generator are '+f(a['approximation'][0]['truth_RMS_against_fine_generator_um'])+' and '+f(a['approximation'][1]['truth_RMS_against_fine_generator_um'])+' µm for reference surface spacings 0.08 and 0.04 mm (bulk spacing 0.50 mm). These differences combine discretization and nominal-elasticity approximation; they do not isolate a stiffness-removal effect. This test precedes parameter interpretation. For each resolution, two designs contain exactly 30 observations: 30 uniformly selected retained indices; or the 18 former omissions plus 12 retained anchors. Table S36 lists the indices and approximation errors. Observations are noise-free, phase is known and gain is unity. A fitted constant offset is eliminated separately on each design; the 0.1 µm residual scale is an objective convention, not a simulated noise realization or calibrated discrepancy covariance.')
    add('Bounds are C_a∈[0.005,0.040] mm, s_a∈[0.55,0.90], C_d∈[0,0.025] mm and s_d∈[0.15,0.70]. Parameter scales are (0.020,0.20,0.010,0.30); forward finite-difference steps are (0.0001,0.001,0.0001,0.001), in native units, reversed at an upper bound. Trust-region least squares uses at most 25 residual evaluations per moving-contact attempt, ftol=xtol=10⁻⁶ and gtol=10⁻⁵. The 0.08 mm reference uses starts (0.018,0.72,0.008,0.45) and (0.025,0.82,0.014,0.60); its lowest-objective full fit initializes the 0.04 mm reference. Restricted C_d=0 fits fix s_d=0.50. A projected-energy analytical control uses the same data, bounds, designs and starts with its analytic tangent and a 600-evaluation budget. Equal observation count is enforced, but equal numerical model cost is not claimed. All '+str(attempts)+' attempts, including '+str(failures)+' flagged nonconverged, are retained (Table S35); no global-minimum certificate or likelihood confidence interval is assigned.')
    cap('Table 10 Equal-count deterministic inverse controls. Depths are µm, start coordinates dimensionless. The minimum final objective selects a full and a restricted fit within each model/design; selection includes nonconverged attempts. Fit and null RMS use the 30 training stations after offset removal. Cycle RMS uses all 120 stations and includes the training observations; it is a prediction check, not an independent validation set. C denotes a solver convergence flag; L denotes an evaluation-limit or other unsuccessful termination. These flags do not certify parameter recovery.')
    t=table(d,['Model / design','C_a / s_a','C_d / s_d','Fit RMS','Null RMS','Cycle RMS','Flag'],rows,[3.5,2,2,1.8,1.8,2,1.2]);anchor._p.addprevious(t._tbl)
    for cell in t.rows[0].cells:
        p=cell.paragraphs[0];write(p,p.text)
        for r in p.runs:r.font.size=Pt(9);r.bold=True
    initial=[r for r in inv if r['file']=='inverse_reference_s0.08.json' and r['design']=='interior' and not r['restricted'] and 'theta' in r]
    add('The two coarse interior full fits give dedendum depths '+f(initial[0]['theta'][2]*1000)+' and '+f(initial[1]['theta'][2]*1000)+' µm, with starts '+f(initial[0]['theta'][3])+' and '+f(initial[1]['theta'][3])+', despite training RMS values '+f(initial[0]['residual_RMS_um'])+' and '+f(initial[1]['residual_RMS_um'])+' µm. Thus a convergence flag and a small transmission residual do not by themselves certify the relief estimate. Table S35 reports the normal-relief-field error against the known truth. Table S36 additionally evaluates the 90 unused stations with the offset fixed from the 30 training observations; unlike the complete-cycle centred comparison, this check does not refit the offset on those unused values. It remains a virtual cross-operator prediction test, not physical validation.')
    bi=next(r for r in best if r['file']=='inverse_reference_s0.04.json' and r['design']=='interior');bm=next(r for r in best if r['file']=='inverse_reference_s0.04.json' and r['design']=='with_transitions')
    add('At the 0.04 mm reference spacing, the selected interior and mixed fits estimate C_d='+f(bi['theta'][2]*1000)+' and '+f(bm['theta'][2]*1000)+' µm, and s_d='+f(bi['theta'][3])+' and '+f(bm['theta'][3])+', respectively, against the generating 10 µm and 0.50. Their normal-relief-field RMS errors are '+f(bi['normal_relief_RMS_um'])+' and '+f(bm['normal_relief_RMS_um'])+' µm. These are conditional point fits under deterministic discrepancy, not calibrated recovery intervals.')
    add('The fitted profiles and residuals must be interpreted together with the at-truth approximation discrepancy, the finite optimization budget and the two-grid changes. A lower restricted-fit residual than a selected full fit is an optimization warning, since the full parameter domain contains the restricted model. Conversely, a lower full-fit residual alone does not establish unique recovery under model discrepancy. The equal-count comparisons quantify the role of these stations for the declared discrete operators; they do not establish a universally optimal sampling design or measured recovery of certified relief.')
    add('Independent mechanical checks use CalculiX 2.23 [48] on shared plane-strain geometries and meshes, with independently implemented contact and FE assembly. Finite-sliding node-to-surface penalty tests at entry, interior and exit, and hard-mortar entry controls, are retained separately (Table S34). Hard-mortar entry approach differs from the bilateral implementation by 0.100 and 0.0635 µm at the two matched resolutions. These are selected nominal contact checks, not independent full-cycle or inverse-profile validation. Extruded C3D6 elements with constrained out-of-plane displacement reproduce plane strain; this is not a three-dimensional face-width study. Prior selected-phase geometry-removal and regularization/order controls are also archived unchanged.')
    patch('The cross-operator experiments distinguish','The cross-operator experiments distinguish detecting a relief effect from reconstructing its geometry. The isolated 24/24 fixed-normal dedendum signal is close to the analytical prediction, but this agreement concerns an RMS response difference, not complete waveforms or inverse parameters. Restricted fits and profile objectives test compensating alternatives. In that historical study, bulk refinement stabilizes the isolated signal while substantial inverse-residual changes remain. Its 102 retained observations cannot establish insufficiency of all possible observations. Section 4.9 supplies a separate bilateral moving-contact generator at all 120 stations and tests equal-count designs including the former omissions. It retains closure and refinement discrepancies and explicitly measures the nominal-elasticity inverse approximation at the truth. These calculations do not retroactively change the historical fixed-normal data or certify continuum-converged inversion. Interpretation remains conditional on phase design, bounds, mesh, operator and objective scale; deterministic discrepancy prevents a nominal likelihood threshold from certifying physical confidence intervals.')
    patch('Absolute parameter accuracy would require','Absolute parameter accuracy requires a geometrically faithful reference or measured data with known modifications, compatible boundary conditions, calibrated scale and resolved angular waveforms. The material-removal control in Section 4.5 reassembles elasticity while keeping candidate contact geometry fixed, isolating a theorem hypothesis. The full-cycle generator in Section 4.9 updates both the modified geometry and its FE stiffness, whereas its inverse retains nominal elasticity. Neither uses a certified manufactured root fillet. These experiments delimit the consequences of declared assumptions and identify what physical reconstruction still requires.')
    patch('Limitations and outlook.','Limitations and outlook. All inversions use synthetic data; the external amplitude reference is a published FE benchmark, not measured TE from gears with certified modifications. The analytical operator reduces each pair to one effective normal contact. All FE experiments are frictionless, quasistatic and plane-strain; dynamic effects, mounting deviations [17], wide-face effects [16] and the manufactured root fillet remain outside this reduction. Historical gap-only inverses retain fixed sections, normals and coordinates. Section 4.9 resolves the complete discrete cycle for the assumed contour with a separate full-geometry generator, but its moving-contact inverse retains nominal elasticity. Closure errors, two-grid changes and unsuccessful optimization attempts are reported; continuum-converged inversion is not established. Selected independent-solver checks validate neither the complete cycle nor physical relief recovery. The stress controls add periodic errors and known/estimated covariance under prescribed synthetic alternatives, without measured calibration. Future work should apply the support diagnostic to measured TE with certified relief, characterize fillet and face-width effects, and calibrate discrepancy before assigning physical uncertainty through a Bayesian framework [40,41]. Table S27 maps the original follow-ups; the discrete-cycle and periodic-error parts are now addressed conditionally, while physical validation remains open. A single deterministic FE difference does not identify a stochastic discrepancy covariance without replication or additional assumptions. The current archive also remains without a repository DOI.')
    p=next(p for p in d.paragraphs if p.text.startswith('The stress controls extend'))
    patch('The stress controls extend',p.text+' The updated-contact experiment additionally provides a complete discrete cycle and equal-count transition controls, while leaving continuum-converged and physically measured parameter recovery unestablished.')
    patch('Data availability.','Data availability. MMT_reproducibility_v19.zip supplies the current construction and analysis code, full-cycle observations, saved contact states, all inverse attempts, numerical audits, software/source provenance and a SHA-256 manifest. The preceding v18 archive preserves 1100 selected stress cases, 3300 final fitting attempts and 300 covariance-pilot attempts; it and the selected-phase mechanical evidence are included as unchanged companion archives. Large regenerable body-compliance caches and solver binaries are excluded with explicit recipes. The public version-13 baseline at https://github.com/romusan/gears-inversion-reproducibility/tree/manuscript-v13 does not contain subsequent controls. No repository DOI is currently assigned.')
    # Normalize a program identifier, preserving its bibliographic meaning.
    p=next(p for p in d.paragraphs if p.text.startswith('[8] '));patch('[8] ',p.text.replace('419 A study','A study').replace('2000.75 (2000)','2000.75, conference paper 419 (2000)'))
    refs=[
      '[46] F. Bruzzone, T. Maggi, C. Marcellini, C. Rosso, Gear Teeth Deflection Model for Spur Gears: Proposal of a 3D Nonlinear and Non-Hertzian Approach, Machines 9 (2021) 223. https://doi.org/10.3390/machines9100223',
      '[47] S.-Y. Ye, S.-J. Tsai, A computerized method for loaded tooth contact analysis of high-contact-ratio spur gears with or without flank modification considering tip corner contact and shaft misalignment, Mechanism and Machine Theory 97 (2016) 190–214. https://doi.org/10.1016/j.mechmachtheory.2015.11.008',
      '[48] G. Dhondt, CalculiX CrunchiX USER’S MANUAL, version 2.23. https://www.dhondt.de/ (accessed 1 November 2026).']
    for text in refs:
        p=paragraph(d,text)
        for r in p.runs:r.font.size=Pt(9)
    d.core_properties.version='19';d.save(OUT/'MMT_manuscript_Q1_revision_v19_clean.docx')
    s=Document(OLD/'MMT_supplementary_Q1_revision_v18.docx')
    p=next(p for p in s.paragraphs if p.text.startswith('Supplementary Table S27 '))
    write(p,'Supplementary Table S27 Follow-up map for the scope summarized in Table 11. Entries are updated with the discrete virtual-cycle controls of Section 4.9. Remaining physical and calibration experiments are proposals, not completed results or prerequisites claimed to have been satisfied.')
    paragraph(s,'Full-cycle bilateral contact and inverse controls','Heading 1')
    def sc(text):
        p=paragraph(s,text);p.paragraph_format.keep_with_next=True;p.paragraph_format.keep_together=True
    sc('Supplementary Table S33 Complete discrete-cycle audit and refinement. Each grid has 360 cycle observations plus three closure controls. All 18 formerly omitted indices are solved for each of the three profiles. ΔTE is the RMS difference of mean-removed pointwise waveforms, not a difference of RMS values. Closure is f=1 minus f=0 and is not corrected. Residual tolerances are implementation checks, not continuum error bounds.')
    sr=[]
    for q in a['cycle']:
        for case in ['nominal','addendum','combined']:
            sr.append([f(q['step_mm'])+' / '+f(q['h_mm']),case,f(q['cases'][case]['centered_RMS_um']),f(q['cases'][case]['closure_um']),f(a['cycle_centered_refinement_RMS_um'][case])])
    table(s,['Surface / bulk mm','Profile','TE RMS µm','Closure µm','ΔTE grids µm'],sr,[3,2.5,3,3,3.5])
    paragraph(s,'Isolated centred dedendum RMS: '+f(coarse['dedendum_centered_RMS_um'])+' and '+f(fine['dedendum_centered_RMS_um'])+' µm; contrast refinement RMS '+f(a['dedendum_contrast_refinement_RMS_um'])+' µm. Maximum saved-state audit active gap '+f(max(r['active_gap_um'] for r in audit['results']))+' µm; minimum gap '+f(min(r['minimum_gap_um'] for r in audit['results']))+' µm; maximum torque relative error '+f(max(r['torque_relative_error'] for r in audit['results']))+'; maximum FE residual '+f(max(r['elastic_relative_error'] for r in audit['results']))+'. Full per-state values are in audit_cycle_v19.json.')
    paragraph(s,'Refinement RMS on the 18 former omissions (nominal, addendum, combined): centred '+', '.join(f(a['transition_centered_refinement_RMS_um'][k]) for k in ['nominal','addendum','combined'])+' µm; uncentred '+', '.join(f(a['transition_raw_refinement_RMS_um'][k]) for k in ['nominal','addendum','combined'])+' µm. Centring uses each complete 120-station waveform, without affine detrending or closure enforcement. These are observed two-grid differences, not certified error estimates.')
    meshes=json.loads((OUT/'experiments/mesh_metadata.json').read_text())
    paragraph(s,'Mesh parameter h sets a near-boundary target h/3 and a far-field maximum 3h; it is not a uniform element size. The bore has 96 boundary vertices. Body mesh counts (nodes / linear triangles / condensed displacement DOFs): '+ '; '.join(m['tag']+': '+str(m['nodes'])+' / '+str(m['triangles'])+' / '+str(m['condensed_dofs']) for m in meshes)+'. Each modified pinion uses its own mesh; the nominal wheel is reused.')
    sc('Supplementary Table S34 Selected independent-solver controls at 300 Nm. All are nominal geometry. Node-to-surface (N2F) tests use finite sliding; hard mortar uses the documented incremental pairing. Penalty stiffness has units N/mm³. These shared-mesh plane-strain checks do not constitute independent full-cycle validation.')
    table(s,['Phase','Surface / bulk mm','Contact','Penalty','Approach µm'],[
        ['Entry','0.04 / 0.50','N2F','10⁸','28.0965'],['Entry','0.04 / 0.50','N2F','10⁹','28.0777'],['Entry','0.04 / 0.50','Hard mortar','—','28.0604'],['Entry','0.02 / 0.35','Hard mortar','—','28.3635'],['Interior','0.04 / 0.50','N2F','10⁹','25.9566'],['Exit','0.04 / 0.50','N2F','10⁹','27.7058']],[2,3,3,2,4])
    sc('Supplementary Table S35 Every new inverse attempt, with termination flags. Model labels identify the nominal-elasticity reference spacing or analytical control. Full and restricted fits use identical design observations. The list includes all attempts; Table 10 selects the smallest final objective within each class. P is normal-relief-field RMS error on 1001 uniform normalized involute coordinates, in µm; it excludes the assumed blend and tip extension. C/L are solver success/unsuccessful flags, not correctness certificates. Errors, iterations and starts are retained in the machine-readable files.')
    br=[]
    for i,r in enumerate(inv):
        label='Analytic' if r['file']=='inverse_analytic.json' else r['file'].replace('inverse_reference_s','').replace('.json','')
        th=r.get('theta');br.append([str(i+1),label,'Mixed' if r['design']=='with_transitions' else 'Interior','Null' if r['restricted'] else 'Full',', '.join(f(v) for v in th) if th else 'Error',f(r.get('residual_RMS_um')),f(r.get('normal_relief_RMS_um')),'C' if r.get('success') else 'L'])
    table(s,['#','Model','Design','Fit','θ (mm, –, mm, –)','RMS µm','P µm','Flag'],br,[.9,2,1.6,1,4.5,1.5,1.4,1.1])
    sc('Supplementary Table S36 Equal-count designs and inverse-approximation check. Target data are the 120-station combined profile from the 0.02/0.35 mm full-geometry generator. Every design has 30 observations, unity gain, known phase and an eliminated offset. At-truth discrepancies compare separately mean-removed complete curves; no random noise or calibrated uncertainty interval is used.')
    eligible=[i for i in range(120) if i not in a['excluded_indices']]
    INTERIOR=[eligible[int(i*(len(eligible)-1)/29)] for i in range(30)]
    DESIGN=sorted(a['excluded_indices']+[0,10,20,36,44,52,60,68,76,84,100,110])
    table(s,['Quantity','Specification'],[['Interior indices',', '.join(map(str,INTERIOR))],['Mixed indices',', '.join(map(str,DESIGN))],['0.08 mm reference, truth RMS µm',f(a['approximation'][0]['truth_RMS_against_fine_generator_um'])],['0.04 mm reference, truth RMS µm',f(a['approximation'][1]['truth_RMS_against_fine_generator_um'])],['Excluded historical indices',', '.join(map(str,a['excluded_indices']))]],[4,11])
    paragraph(s,'Unused-station checks use the 90 indices outside each design and an offset estimated only from its 30 training observations. Best full-fit RMS values (µm): '+ '; '.join(('Analytical' if r['file']=='inverse_analytic.json' else r['file'].replace('inverse_reference_s','Reference ').replace('.json',''))+' / '+('Interior' if r['design']=='interior' else 'Mixed')+' = '+f(r['unseen_stations_RMS_um']) for r in best)+'. The mean-removed complete-cycle metric in Table 10 instead eliminates its offset over all 120 points. Neither metric is measured validation.')
    # Update prospective mapping without altering any historical numerical table.
    followup={
        'Fixed-compliance invariance':'Section 4.9 updates geometry and stiffness through a separate complete virtual generating cycle; the new inverse retains nominal elasticity. Physical manufactured-geometry validation remains open.',
        'FE gap comparison':'Section 4.9 resolves all 18 former omissions with bilateral contact on the assumed sharp-tip/blended-root contour, and repeats equal-count inversion at two reference spacings. Certified fillet geometry and continuum-converged recovery remain open.',
        'Material removal':'Complete-cycle geometry removal and reassembled stiffness are now tested for the assumed virtual profiles (Section 4.9). Extension to certified manufacturing geometry remains open.'}
    for row in s.tables[26].rows:
        if row.cells[0].text in followup:
            p=row.cells[1].paragraphs[0];write(p,followup[row.cells[0].text])
            for r in p.runs:r.font.size=Pt(9)
    s.core_properties.version='19';s.save(OUT/'MMT_supplementary_Q1_revision_v19.docx')
    h=Document(OLD/'Highlights_v18.docx');bullets=[
        'Unloaded relief is exactly invisible under fixed geometry and compliance',
        'Coupled tooth-pair compliance preserves the unloaded-support invariance',
        'A bilateral moving-contact model resolves all 120 virtual cycle stations',
        'Equal-count designs test stations omitted by a fixed-normal generator',
        'Signal detection alone does not establish recovery of physical relief']
    pp=[p for p in h.paragraphs if p.text.startswith('• ')];assert len(pp)==5 and all(len(x)<=85 for x in bullets)
    for p,b in zip(pp,bullets):write(p,'• '+b)
    h.core_properties.version='19';h.save(OUT/'Highlights_v19.docx')
    cover=Document(OLD/'Cover_letter_MMT_v18.docx')
    for p in cover.paragraphs:
        if 'v18' in p.text:write(p,p.text.replace('v18','v19'))
        if p.text.startswith('The manuscript addresses') or p.text.startswith('Our manuscript'):
            write(p,'The manuscript establishes a sufficient unloaded-support invariance condition, including coupled compliance, and distinguishes signal detection from parameter recovery through synthetic likelihood, Monte Carlo and FE controls. The revised computational evidence adds a bilateral moving-contact cycle at 120 stations for three profiles and two resolutions, selected independent CalculiX checks, and equal-count inverse designs. All results are numerical; no measured certified-relief reconstruction is claimed.')
        if p.text.startswith('The submission includes'):
            write(p,'The submission includes supplementary Tables S1–S36, Highlights and a version-19 reproducibility archive. The complete new numerical cycle retains 720 observations and six closure controls, with all attempted inverse fits and numerical discrepancies. The unchanged preceding evidence includes 1100 synthetic stress selections, 3300 final attempts and 300 covariance pilots. These controls do not replace measured-data validation. The public v13 baseline predates these additions; no current-version repository DOI is assigned.')
        if p.text.startswith('The manuscript explicitly'):
            write(p,'The manuscript reports its negative findings: none of the four analytical formulations meets the adopted external amplitude target, and the historical fixed-normal FE observations do not identify the dedendum. The new cycle resolves the discrete contact states, while inverse estimates remain dependent on the operator and mesh. These results connect contact mechanics with inverse stability and are relevant to the journal’s readership working on gear modelling, transmission error and microgeometry.')
    cover.core_properties.version='19';cover.save(OUT/'Cover_letter_MMT_v19.docx')
    (OUT/'editorial_changes_v19.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2))
    (OUT/'table10_expected.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2));print('v19 DOCX',len(abstract.split()),'abstract words',attempts,'new inverse attempts')
